<main id="main"><?php while ( have_posts() ) : the_post(); $image = get_post_meta( get_the_ID(), '_khaiwal_demo_image', true ); $title_hi = get_post_meta( get_the_ID(), '_khaiwal_demo_title_hi', true ); ?><section class="article-hero"><div class="container article-container"><div class="breadcrumb"><a href="<?php echo esc_url( home_url( '/' ) ); ?>"><?php echo khaiwal_text( 'Home', 'होम' ); ?></a><span>/</span><a href="<?php echo esc_url( home_url( '/#journal' ) ); ?>"><?php echo khaiwal_text( 'Journal', 'जर्नल' ); ?></a></div><div class="eyebrow"><span class="eyebrow-dot"></span><?php echo khaiwal_text( 'THE KHAIWAL JOURNAL', 'खाईवाल जर्नल' ); ?></div><h1><?php echo $title_hi ? khaiwal_text( get_the_title(), $title_hi ) : esc_html( get_the_title() ); ?></h1><p><?php echo esc_html( get_the_date( 'F j, Y' ) ); ?></p></div></section><article class="article-body container article-container"><div class="article-cover"><?php if ( has_post_thumbnail() ) { the_post_thumbnail( 'large' ); } elseif ( $image ) { ?><img src="<?php echo esc_url( get_template_directory_uri() . '/assets/images/' . basename( $image ) ); ?>" alt="<?php echo esc_attr( get_the_title() ); ?>"><?php } ?></div><div class="prose"><?php the_content(); wp_link_pages(); ?></div><?php if ( comments_open() || get_comments_number() ) { comments_template(); } ?><a class="back-link" href="<?php echo esc_url( home_url( '/#journal' ) ); ?>"><?php echo khaiwal_icon( 'left' ); ?> <?php echo khaiwal_text( 'Back to the journal', 'जर्नल पर वापस जाएँ' ); ?></a></article><?php endwhile; ?></main>
